func OnJoyConnectionChanged(cb func(device Device, connected bool), flags ...Signal.Flags) {
	var flags_together Signal.Flags
	for _, flag := range flags {
		flags_together |= flag
	}
	once.Do(singleton)
	gd.ObjectConnect(gdclass.GetInput(self[0])[0], gd.NewStringName("joy_connection_changed"), gd.NewCallable(cb), int64(flags_together))
}



